import{_ as o,C as r,c as l,o as n,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Sales details","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/reporting/sales-details.md","filePath":"master/sales/point-of-sale/reporting/sales-details.md","lastUpdated":1792041590000}'),i={name:"master/sales/point-of-sale/reporting/sales-details.md"};function d(h,e,m,p,c,u){const a=r("ImagePopup");return n(),l("div",null,[e[0]||(e[0]=t('<h1 id="sales-details" tabindex="-1">Sales details <a class="header-anchor" href="#sales-details" aria-label="Permalink to &quot;Sales details&quot;">​</a></h1><p>The Sales details report gives a full picture of a period in one screen. It shows the order totals, how customers paid, the taxes collected and every product sold. Use it at the end of a day or week, or when your accountant asks what the registers sold.</p><blockquote><p><strong>In simple words:</strong> Pick a date range and a register. The page tells you what was sold, how it was paid and how much tax it carried.</p></blockquote><h2 id="open-the-report" tabindex="-1">Open the report <a class="header-anchor" href="#open-the-report" aria-label="Permalink to &quot;Open the report&quot;">​</a></h2><p>Go to <code>Point of Sale → Reporting → Sales Details</code>.</p>',5)),s(a,{src:"/images1/pos/sales_details_overview.png",alt:"Sales Details page with dates 01/10/2026 to 12/10/2026 and All terminals showing Summary, Payments, Taxes and Products Sold"}),e[1]||(e[1]=t('<h2 id="set-the-filters" tabindex="-1">Set the filters <a class="header-anchor" href="#set-the-filters" aria-label="Permalink to &quot;Set the filters&quot;">​</a></h2><ol><li><strong><em>Start date:</em></strong> The first day to include. It starts on the first day of the current month.</li><li><strong><em>End date:</em></strong> The last day to include. It starts on today.</li><li><strong><em>Terminal:</em></strong> Choose <strong>All terminals</strong> or one register.</li></ol>',2)),s(a,{src:"/images1/pos/sales_details_filters.png",alt:"Sales Details filter bar with TechNest Electronics selected as the terminal"}),e[2]||(e[2]=t('<p>The report refreshes after each change.</p><h2 id="read-the-sections" tabindex="-1">Read the sections <a class="header-anchor" href="#read-the-sections" aria-label="Permalink to &quot;Read the sections&quot;">​</a></h2><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><ul><li><strong><em>Orders:</em></strong> The number of settled orders.</li><li><strong><em>Untaxed:</em></strong> The total before tax.</li><li><strong><em>Taxes:</em></strong> The tax total.</li><li><strong><em>Total:</em></strong> The grand total of those orders.</li></ul><h3 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h3><p>One line for each payment method, such as <strong>Cash</strong>, with the amount received. Use it to compare with what is in the drawer or on the card terminal.</p><h3 id="taxes" tabindex="-1">Taxes <a class="header-anchor" href="#taxes" aria-label="Permalink to &quot;Taxes&quot;">​</a></h3><p>One line for each tax, with the tax amount. When your products carry no tax, the section reads <strong>No taxes in this period.</strong></p><h3 id="products-sold" tabindex="-1">Products Sold <a class="header-anchor" href="#products-sold" aria-label="Permalink to &quot;Products Sold&quot;">​</a></h3><p>A table with these columns, sorted by the largest total first:</p><ul><li><strong><em>Product:</em></strong> The product name.</li><li><strong><em>Quantity:</em></strong> The units sold. Returned units are subtracted.</li><li><strong><em>Untaxed:</em></strong> The sales amount before tax.</li><li><strong><em>Total:</em></strong> The sales amount with tax.</li></ul><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p>Use <strong>TechNest Electronics</strong> from 1 to 12 October 2026.</p><p>Summary: 3 orders, untaxed 6,597.00, taxes 0.00, total 6,597.00.</p><p>Payments:</p><table tabindex="0"><thead><tr><th>Method</th><th>Amount</th></tr></thead><tbody><tr><td>Cash</td><td>6,597.00</td></tr></tbody></table><p>Products Sold:</p><table tabindex="0"><thead><tr><th>Product</th><th>Quantity</th><th>Untaxed</th><th>Total</th></tr></thead><tbody><tr><td>BudsAir Wireless Earbuds</td><td>1.00</td><td>3,999.00</td><td>3,999.00</td></tr><tr><td>Glide Wireless Mouse</td><td>2.00</td><td>2,598.00</td><td>2,598.00</td></tr><tr><td>Nova X5 Smartphone 128GB</td><td>0.00</td><td>0.00</td><td>0.00</td></tr></tbody></table><p>The Nova X5 smartphone was sold once and returned once, so it nets to zero. It still shows in the list.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The cash amount is lower than the 7,000.00 the customer handed over for TNE/00001. The 403.00 change went back to the customer, so only the order value stays.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Reporting overview</a></li><li><a href="./orders-report.html">Orders report</a></li><li><a href="./session-report.html">Session report</a></li><li><a href="./../orders-payments/payments.html">Payments</a></li></ul>',22))])}const _=o(i,[["render",d]]);export{f as __pageData,_ as default};
